__forceinline unsigned Actor::SelectIdleGroup(int group)
{
    Animation* current = GetAnimation();
    unsigned id;
    if (!current)
        id = 255;
    else
    {
        unsigned bits = moveFlags ? moveFlags->GetFlags() : 0;
        int stance = 0;
        int style = 0;
        Item* equipment = process->GetWeapon();
        if (bits & 0x800)
            stance = 2;
        else if (bits & 0x2000)
            stance = 3;
        else if (bits & 0x400)
            stance = 1;
        if ((!GetState() && (Actor_GetWantWeaponDrawn() || attacking)) || process->IsWeaponOut() ||
            (this == DAT_0107a104 && DAT_0107a104->playerState) ||
            (equipment && (process->IsWeaponOut() || Actor_GetWantWeaponDrawn())))
        {
            if (equipment)
                style = DAT_00f4eb6c[equipment->GetForm()->kind];
            else
                style = 1;
        }
        bool mode = process ? process->GetMode() : false;
        unsigned short mapped = (unsigned short)FUN_0054b730(stance, style, group, mode);
        id = current->FUN_0045d6a0(mapped, 0);
    }
    return id;
}

