void NiPoint3::Unitize()
{
    float fLength = Length();
    if (fLength > 1e-06f)
    {
        float fRecip = 1.0f / fLength;
        x *= fRecip;
        y *= fRecip;
        z *= fRecip;
    }
    else
    {
        x = 0.0f;
        y = 0.0f;
        z = 0.0f;
    }
}

